    return error(r,"400 Bad Request","Choose a whole-number refresh interval from 300 to 86400 seconds.");
  if(!request["enabled"].isUnbound() && !request["enabled"].is<bool>())
    return error(r,"400 Bad Request","Enabled must be true or false.");
